export function getKauGeneratedProgram(code){
 const key=String(code||'').trim().toUpperCase();
 const p=KAU_GENERATED_PROGRAMS[key];
 if(!p)return null;
 const full=p.coverage==='complete'||p.coverage==='choice-required';
 const courses=(p.rows||[]).map((r,i)=>({
  ...r,term:Number(r.term)||null,originalTerm:Number(r.term)||null,__slOriginalTerm:Number(r.term)||null,__slOriginalIndex:i,
  status:'remaining',credited:false,isCredited:false,programmeSource:'karlstad-program-database',programmeCategory:r.category||r.type||''
 }));
 return {
  found:true,structureAvailable:full,courses,
  program:{name:p.name,code:key,university:'Karlstads universitet'},
  sourceUrls:p.sourceUrls?.length?p.sourceUrls:[p.sourceUrl].filter(Boolean),
  source:'karlstad-program-database',confidence:full?'official-verified-persisted':'official-audited-partial',coverage:p.coverage,
  quality:{complete:full,expectedTerms:p.expectedTerms,completeTerms:p.completeTerms,totalHp:p.hp,persisted:true,audited:true,auditedAt:p.auditedAt,reason:p.reason,structureKind:p.structureKind,underPlanning:p.underPlanning},
  policy:'Karlstad catalogue is fully audited. Complete structures are served locally; official partial, individualized or unpublished portions remain explicitly marked and are never invented.'
 };
}
